namespace MmaManager.Core.Sim.Generation.Origins;

public static partial class OriginsChapters
{
    // ===================== ERA 4: THE RULES (2001-2007) =====================
    private static OriginsChapter[] Era4() => new[]
    {
        C("unified-rules", 4, "One Set of Rules", 96, 156, A("sanction-spreads", "rounds-and-judges"),
            "A share of the sport's regions have adopted a common rule set and the commissions publish it.",
            World("SanctionedRegionsAtLeast", 15),
            A(),
            A("Every sanctioned promotion uses the same rule set: rounds, judges, gloves, a list of fouls. Rankings are recognised and title shots follow them."),
            null, null,
            N("The sport becomes a sport",
              "{Year}. For a decade every promotion has had its own idea about the rules: how long a round lasts, what counts as a foul, who judges what. Now, in a meeting room in a hotel conference centre, commissioners from a dozen regions and the leading promoters agree on one set. Five-minute rounds, three judges, a list of forbidden strikes and a ten-point scoring system. It takes four hours and one argument about elbows. A fighter can now move between promotions and know what the rules are. Rankings finally mean the same thing everywhere."),
            "One set of rules: commissions and promoters agree on a common code, and rankings mean something.",
            "A world shift; no player variant."),

        C("weight-ladder-middle", 4, "The Middle of the Ladder Fills In", 90, 144, A("first-weight-split"),
            "The first promotion to crown a champion in the welterweight or light-heavyweight class.",
            First("CrownChampionInClass:Welterweight"),
            A("WeightClass:LightHeavyweight", "WeightClass:Welterweight"),
            A("The light-heavyweight and welterweight classes open; middle-sized men finally have divisions."),
            N("{Org} crowns {Fighter} in a new class",
              "The two-class sport never fit the men in the middle, and {Org} has finally fixed it: {Fighter} is crowned in {City} as the first champion of a new division. {Founder} says it is simply arithmetic. The fighters say it is the first time they have not had to cut or bulk to fit. Matchmakers will no longer need to explain to the public why a seventy-kilo man faced a hundred."),
            N("{Org} opens a new weight class",
              "{Fighter} of {Org} has won the first title in a new weight class in {City}. The ladder of divisions, which started with heavy and light, now has a middle. Other promotions will follow because their fighters will ask them to. For anyone between the extremes it is the best news in years. Local gyms say they will build a division of their own at once."),
            N("Four classes, then five",
              "{Year}. The first weight line, drawn at one hundred and eighty-five pounds, left most fighters on the wrong side of someone's idea of fair. Now the divisions multiply: a light-heavyweight class for the men who are too big to be small and too small to be huge, and a welterweight class for the many who fall between. A fighter who spent his career guessing the weight of his opponent now gets a number and a fair fight."),
            "The ladder fills in: light-heavyweight and welterweight arrive."),

        C("weight-ladder-lower", 4, "The Smaller Men Get Divisions", 108, 168, A("weight-ladder-middle"),
            "The first promotion to crown a champion in the lightweight or featherweight class.",
            First("CrownChampionInClass:Lightweight"),
            A("WeightClass:Lightweight", "WeightClass:Featherweight"),
            A("The lightweight and featherweight classes open."),
            N("{Org} gives the lighter men their night",
              "The sport's lightest fighters have always been told the crowds want the big ones. {Org} has proved otherwise: in {City}, {Fighter} becomes the first champion in a new lower weight class, and the hall is louder than it has been all year. The smaller men are faster, more technical and harder to hit. {Founder} intends to build a division around exactly that."),
            N("{Org} crowns {Fighter} at the lighter weight",
              "{Org} has launched a lighter class and crowned {Fighter} in {City}. The crowd, expecting a sideshow, found the best fight on the card. The smaller men move faster and finish differently, and the sport's older fans, who thought they had seen everything, are rethinking. His promoter says the next card will put two of the lighter men at the top of the bill, and the box office agrees."),
            N("Lightweight and featherweight",
              "{Year}. For a decade the sport has been built around big men. The first class below welterweight arrives and, to many people's surprise, works: smaller fighters are quicker, more varied and more willing to take a risk. A second, lighter class follows within a few seasons. The trade papers begin to argue that the real talent of the sport lives below one hundred and fifty-five pounds, and the gyms begin to agree."),
            "Lightweight and featherweight open: smaller men get their own champions."),

        C("beer-and-energy-drinks", 4, "Beer and Energy Drinks Move In", 84, 156, A("equipment-houses", "first-sanctioned-state"),
            "The first promotion to sign a brewery or an energy-drink maker.",
            First("SignSponsor:Brewery"),
            A("Sponsor:Brewery", "Sponsor:EnergyDrink"),
            A("Breweries sponsor on attendance; energy-drink brands sponsor on star power."),
            N("{Partner} comes ringside with {Org}",
              "{Partner} has signed to put its name across {Org}'s canvas and its product in every bar within a hundred miles of {City}. {Founder} has been waiting for exactly this kind of company: young, loud and willing to pay for a crowd. The deal is tied to attendance and fame, and {Org} has plenty of both. It is the first time the sport has been sold as a night out."),
            N("{Partner} signs on with {Org}",
              "A drinks company, {Partner}, has signed with {Org}: logo on the canvas, product in the arena. It is the sort of sponsor that follows a crowd, and the crowd is large. The sport has noticed that its audience buys beer. Its marketing director, who has never been to a fight, is seen at the first one wearing a branded jacket and a very wide smile."),
            N("Beer and fizz",
              "{Year}. Brewers have always known that a ring is a good place to put a banner. Now, with the sport sanctioned and the crowds younger and louder, the first breweries sign on, and a newer kind of advertiser follows: the energy drink, selling stamina by the can. Their money is not small and their requirements are plain: a big crowd, a famous face, a young audience. The sport finds that it has stumbled into one of the most valuable demographics in the world."),
            "Beer and energy drinks sign on: the sport is sold as a night out."),

        C("cable-sports-channel", 4, "A Sports Channel Takes It On", 108, 156, A("late-night-cable"),
            "The first promotion to sign a national cable sports channel.",
            First("SignMedia:CableSports"),
            A("Media:CableSports"),
            A("Real rights money from a national sports network; a regular broadcast home for sanctioned promotions."),
            N("{Org} signs with {Partner}",
              "After years of midnight hours and pay-per-view gambles, {Org} now has a home on {Partner}, a national sports channel with real money and a prime slot. {Founder} signs in a boardroom with a view of the harbour and does not say a word until the pen is down. The rights fee is the largest the sport has seen. The conditions are plain: keep the rules, keep the stars, deliver the ratings."),
            N("{Partner} chooses {Org}",
              "{Partner}, a national cable sports channel, has picked {Org} as its first combat sport partner. The fee is substantial. Rival promoters are furious and impressed. A regular national slot will make {Org} a household name in a season. It will also make its next failure a very public one. The contract runs three years, and the company's lawyers have been busy with conduct clauses since Tuesday."),
            N("The sports channel takes the sport",
              "{Year}. A national cable sports channel with space to fill between its basketball and its golf decides to take a chance. {Partner} signs the first sizeable rights deal in the sport's history and slots it on weekday evenings. The ratings are modest and the advertisers are interested. For the first time a promotion can budget for television instead of hoping for it. The sport is on the same dial as everything else."),
            "A sports channel takes it on: {Partner} signs the sport's first real rights deal."),

        C("womens-first-bout", 4, "A Curiosity on the Undercard", 96, 160, A("rounds-and-judges"),
            "The first promotion to stage a bout between two women.",
            First("RunWomensBout"),
            A(),
            A("Women enter the talent intake as a trickle; a few women fighters appear as free agents; their bouts are exhibitions with no division."),
            N("{Org} puts two women in the ring",
              "It is billed as an attraction, slipped between the semi-final and the main event, and {Org} is braced for criticism. {Fighter} and her opponent walk to the ring to a crowd that is not sure what to expect, and to the discovery that two women fight just as skilfully as two men. {Founder} has no plans for a division. The audience, though, is already asking when they can see more."),
            N("{Org} stages the sport's first women's bout",
              "{Org} has put two women on the card in {City}. It is a novelty, and the promotion knows it. The fighters know it as well, and are determined to be remembered for something else. The crowd's reaction, somewhere between curiosity and delight, will be discussed in every promoter's office this week. The commissioner at ringside takes notes, and nobody can tell whether they are good ones."),
            N("The first women's bout",
              "{Year}. A promoter looking for something different puts two women on a card as a novelty between the semi-final and the main event. The bout is short and technical and ends with a handshake, and the crowd talks about it for the rest of the night. There is no plan for a division and no one to organise one. But the idea has been shown to the public, and the public does not seem to mind."),
            "A women's bout appears: a curiosity on the undercard."),

        C("womens-resistance", 4, "Not in Our Ring", 108, 170, A("womens-first-bout"),
            "Follows the first women's bout once a few more have been staged and the objections arrive.",
            World("WomenBoutsAtLeast", 3),
            A(),
            A("Some commissions and carriers refuse women's bouts; sponsors are wary; cards with women's bouts draw mixed gates until the first division is accepted."),
            null, null,
            N("The objections arrive",
              "{Year}. A few more women's bouts, a few more cheers and the objections follow. A commission refuses to license a card that includes one. A carrier asks politely for them to be left out. Some fighters say it is the end of everything; others stay quietly at the back. The women themselves, few and unpaid, keep training and keep taking bouts wherever they are welcome. The resistance is loud but not unanimous: for every door that shuts, another opens a little."),
            "Resistance: some commissions and carriers refuse women's bouts.",
            "A world reaction; no player variant."),

        C("national-brands-sign-on", 4, "Banks and Telephone Companies Take Notice", 120, 168, A("cable-sports-channel"),
            "The first promotion to sign a national brand: a bank, an insurer or a telephone company.",
            First("SignSponsor:National"),
            A("Sponsor:National"),
            A("National brands sponsor title fights of promotions of national reach."),
            N("{Partner} puts its name above the title",
              "{Partner}, a household name, has signed with {Org}, and its logo will sit over every title fight. {Founder} signs in a conference room that smells of fresh carpet. The company wants fights it can show its customers: title bouts, big names, sold-out halls. It is the biggest sponsorship in the sport's history and the first to come from outside the world of sport."),
            N("{Partner} signs with {Org}",
              "{Partner}, a name familiar to every household, has agreed to sponsor {Org}'s title fights. It is a corporate signature in a sport that had been paid for by tyre shops and powder sellers. {Org} has legitimacy now. Its rivals have a deadline. It is not clear whether the company's board has been told yet, but its advertising agency certainly has."),
            N("The household names come in",
              "{Year}. Sponsors with a national reputation had avoided the sport through its worst years. With sanctioning widespread, television established and the crowds respectable, the first big brands sign on: an insurer, a telephone company, a bank. Their requirements are strict: title fights only, stars on the poster, no scandals. Their money is ten times the old kind. For the first time a promotion can plan a year ahead."),
            "National brands sign on: a household name puts its logo over the title fight."),

        C("scene-newzealand-china-philippines-singapore", 4, "The Pacific Rim Opens", 96, 150, A("scene-france-poland-thailand-argentina"),
            "The first promotion to hold a card in one of these countries.",
            First("HoldEventInNewCountry"),
            A("CountryScene:NZL", "CountryScene:CHN", "CountryScene:PHI", "CountryScene:SGP"),
            A("Scenes in New Zealand, China, the Philippines and Singapore wake."),
            N("{Org} breaks ground in {City}",
              "{Org} has brought the sport to {City}, {Country}, and the venue was full an hour before the bell. The locals know the sport from tapes passed between gyms; now they see it live. {Founder} meets officials, gym owners and a flock of young men with questions. By the end of the week {Org} has a local partner, a plan and the first names for a local roster."),
            N("{Org} puts on the first card in {City}",
              "{City}, {Country}, has hosted its first card, courtesy of {Org}. The crowd was noisy, the fighters local and the reception warm. The promotion's rivals have noticed that the Pacific is no longer empty. The promoter walks the arena at midnight with the owner, counting the empty seats and finding none. The mayor, who attended unannounced, is said to have asked when the next one is."),
            N("The Pacific Rim",
              "{Year}. The sport that began in three rooms now arrives in the harbours of the Pacific. In New Zealand, rugby men with wrestler's hands are the first to line up. In China, a government that has always been wary of combat sports licenses a carefully supervised first event. In the Philippines, a nation of boxers and stick-fighters embraces it at once. In Singapore, a promoter with a stadium and a plan finds the market waiting."),
            "Scenes wake in New Zealand, China, the Philippines and Singapore."),
    };
}
